// Test stackalloc with native-sized integers (nint / nuint)
Span<nint> signedSpan = stackalloc nint[4];
for (int i = 0; i < signedSpan.Length; i++)
    signedSpan[i] = i * 10;

Span<nuint> unsignedSpan = stackalloc nuint[4];
for (int i = 0; i < unsignedSpan.Length; i++)
    unsignedSpan[i] = (nuint)(i * 100);

Console.WriteLine($"Span<nint> length: {signedSpan.Length}, values: {signedSpan[0]}, {signedSpan[1]}, {signedSpan[2]}, {signedSpan[3]}");
Console.WriteLine($"Span<nuint> length: {unsignedSpan.Length}, values: {unsignedSpan[0]}, {unsignedSpan[1]}, {unsignedSpan[2]}, {unsignedSpan[3]}");
Console.WriteLine($"Size of nint: {sizeof(nint)} bytes (pointer size on this platform)");

